   /**
    * Creates the provided command.
    * 
    * @param		command ${class.getCreateCommandAlias()}
    * @exception    ProcessingException
    * @exception	IllegalArgumentException
    * @return		Model
    */
	public Model createModel( CreateModelCommand command )
    throws ProcessingException, IllegalArgumentException {

		Model entity = new Model();

		try {
			// --------------------------------------
        	// validate the command
        	// --------------------------------------    	
        	ModelValidator.getInstance().validate( command );    

            entity.setModelId( command.getModelId() );
            entity.setName( command.getName() );
            entity.setTaskDescription( command.getTaskDescription() );
            entity.setModelType( command.getModelType() );
    	    
        	// ------------------------------------------
        	// persist a new one
        	// ------------------------------------------ 
    	    entity = projector.create(entity);
    	    
			LOGGER.log( Level.INFO, "done creating of Model {0} ", entity.toString() );
			
        }
        catch (Exception exc) {
            final String errMsg = "Unable to create Model - " + exc;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }

   /**
    * Update the provided command.
    * @param		command UpdateModelCommand
    * @exception    ProcessingException
    * @exception  	IllegalArgumentException
    * @return		Model
    */
    public Model updateModel( UpdateModelCommand command ) 
    throws ProcessingException, IllegalArgumentException {

	    Model entity = new Model();

    	try {       

			// --------------------------------------
        	// validate 
        	// --------------------------------------    	
        	ModelValidator.getInstance().validate( command );    

            entity.setModelId( command.getModelId() );
            entity.setName( command.getName() );
            entity.setTaskDescription( command.getTaskDescription() );
            entity.setWorkspace( command.getWorkspace() );
            entity.setVersions( command.getVersions() );
            entity.setFeatureSets( command.getFeatureSets() );
            entity.setExperiments( command.getExperiments() );
            entity.setTags( command.getTags() );
            entity.setModelType( command.getModelType() );
        	
        	// ------------------------------------------
        	// persist an existing one
        	// ------------------------------------------ 
        	entity = projector.update(entity);
    	    
			LOGGER.log( Level.INFO, "done saving of Model {0} ", entity.toString() );
    	}
        catch (Exception exc) {
            final String errMsg = "Unable to save Model - " + exc;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
    	
    	return entity;
    }
   
   /**
    * Deletes the associatied value object
    * @param		command DeleteModelCommand
    * @exception 	ProcessingException
    */
    public void delete( DeleteModelCommand command ) 
    throws ProcessingException, IllegalArgumentException {	
        UUID id = null;
        
    	try {  
			// --------------------------------------
        	// validate the command
        	// --------------------------------------    	
        	ModelValidator.getInstance().validate( command );    
        
        	id = command.getModelId();
        	
        	// ------------------------------------------
        	// delete the entity
        	// ------------------------------------------
        	projector.delete(id);

        	LOGGER.log( Level.INFO, "done deleting of Model {0} ", id );

        }
        catch (Exception exc) {
            final String errMsg = "Unable to delete Model using Id = "  + id;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }
    }

    /**
     * Method to retrieve the Model via ModelFetchOneSummary
     * @param 	summary ModelFetchOneSummary 
     * @return 	ModelFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Model getModel( ModelFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ModelFetchOneSummary arg cannot be null" );
    	
    	Model entity = null;
    	UUID id = summary.getModelId();
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	ModelValidator.getInstance().validate( summary );    
        	
        	// --------------------------------------
        	// find a Model using the provided id
        	// --------------------------------------
        	entity = projector.find( id );
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Model with id " + id;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


    /**
     * Method to retrieve a collection of all Models
     *
     * @return 	List<Model> 
     * @exception ProcessingException Thrown if any problems
     */
    public List<Model> getAllModel() 
    throws ProcessingException {
        List<Model> list = null;

        try {        	
        	list = projector.findAll( new FindAllModelQuery() );
        }
        catch( Exception exc ) {
            String errMsg = "Failed to get all Model";
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return list;
    }

    /**
     * assign Workspace on Model
     * @param		command AssignWorkspaceToModelCommand	
     * @exception	ProcessingException
     */     
	public void assignWorkspace( AssignWorkspaceToModelCommand command ) throws ProcessingException {

		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	ModelValidator.getInstance().validate( command );    

			// --------------------------------------
	    	// delegate to the projector
	    	// --------------------------------------    	    	
	    	projector.assignWorkspace(command.getModelId(), command.getAssignment());
		    
		}
        catch( Throwable exc ) {
			final String msg = "Failed to get AnalyticsWorkspace using id " + command.getModelId();
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

    /**
     * unAssign Workspace on Model
     * @param		command UnAssignWorkspaceFromModelCommand
     * @exception	ProcessingException
     */     
	public void unAssignWorkspace( UnAssignWorkspaceFromModelCommand command ) throws ProcessingException {

		try {
			// --------------------------------------
	    	// validate the command
	    	// --------------------------------------    
	    	ModelValidator.getInstance().validate( command );    
	
	    	// --------------------------------------
	    	// delegate to the projector
	    	// --------------------------------------    	    	
	    	projector.unAssignWorkspace(command.getModelId());
		}
		catch( Exception exc ) {
			final String msg = "Failed to unassign Workspace on Model";
			LOGGER.log( Level.WARNING, msg, exc );
			throw new ProcessingException( msg, exc );
		}
	}
	

